// CACHE_NAME and PRECACHE_URLS are generated by `npm run sw` (scripts/build-sw.mjs).
// App files are served cache-first; a new hash installs a new worker that the
// History "Check for Updates" action activates. Workout data lives in IndexedDB
// and localStorage and is never touched here.
const CACHE_NAME = 'maxsnr-7c51269303c4';
const PRECACHE_URLS = [
  '/',
  '/routine/',
  '/history/',
  '/workout/',
  '/app.js',
  '/icons/apple-touch-icon.png',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/js/activity-data.js',
  '/js/backup.js',
  '/js/constants.js',
  '/js/dom.js',
  '/js/health-data.js',
  '/js/icons.js',
  '/js/magnetic-picker.js',
  '/js/navigation.js',
  '/js/render-activity.js',
  '/js/render-analytics.js',
  '/js/render-history.js',
  '/js/render-routine.js',
  '/js/render-today.js',
  '/js/render-workout.js',
  '/js/render-workout/completion.js',
  '/js/render-workout/countdown.js',
  '/js/render-workout/lifting.js',
  '/js/render-workout/plank.js',
  '/js/render-workout/rest.js',
  '/js/render-workout/select.js',
  '/js/render-workout/shared.js',
  '/js/render-workout/stretch.js',
  '/js/routine-data.js',
  '/js/routine-view.js',
  '/js/state.js',
  '/js/storage.js',
  '/js/update-app.js',
  '/js/vendor/canvas-confetti.js',
  '/js/workout.js',
  '/js/workout/adaptation.js',
  '/js/workout/budget.js',
  '/js/workout/coordinator.js',
  '/js/workout/duration-estimator.js',
  '/js/workout/finish.js',
  '/js/workout/health-metrics.js',
  '/js/workout/health-optimizer.js',
  '/js/workout/metrics.js',
  '/js/workout/optimizer-analysis.js',
  '/js/workout/optimizer.js',
  '/js/workout/personalization.js',
  '/js/workout/progression.js',
  '/js/workout/session.js',
  '/js/workout/task-factory.js',
  '/js/workout/timers.js',
  '/manifest.webmanifest',
  '/packages/magnetic-picker/src/magnetic-picker.css',
  '/packages/magnetic-picker/src/magnetic-picker.js',
  '/styles.css',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) =>
      Promise.all(
        PRECACHE_URLS.map(async (url) => {
          const response = await fetch(new Request(url, { cache: 'reload' }));
          if (!response.ok) throw new Error(`Precache failed for ${url}`);
          await cache.put(url, response);
        }),
      ),
    ),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('maxsnr-') && key !== CACHE_NAME)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});

const ROUTE_SHELLS = ['/routine/', '/history/', '/workout/'];

function shellFor(pathname) {
  if (pathname === '/' || pathname === '/index.html') return '/';
  return ROUTE_SHELLS.find((shell) =>
    [shell, shell.slice(0, -1), `${shell}index.html`].includes(pathname),
  );
}

async function respond(request, url) {
  const cache = await caches.open(CACHE_NAME);
  const shell = request.mode === 'navigate' ? shellFor(url.pathname) : null;
  const cached = await cache.match(shell || request);
  if (cached) return cached;
  try {
    return await fetch(request);
  } catch (error) {
    if (request.mode !== 'navigate') throw error;
    return (await cache.match('/')) || Response.error();
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  event.respondWith(respond(request, url));
});
